def validate_and_write():
    print(f"Validating PLAB topics: count = {len(PLAB_TOPICS)}")
    assert len(PLAB_TOPICS) == 100, f"Expected 100 PLAB topics, got {len(PLAB_TOPICS)}"
    for idx, t in enumerate(PLAB_TOPICS):
        title, subj, sys_name, hallmark, ref_l, ref_u = t
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} at PLAB #{idx}: {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} at PLAB #{idx}: {title}"
        assert len(title) > 0 and len(hallmark) > 0, f"Empty title or hallmark at PLAB #{idx}"
        assert ref_u.startswith("https://"), f"Invalid ref URL at PLAB #{idx}: {ref_u}"
    print("  -> All 100 PLAB topics PASSED validation!")

    print(f"Validating AMC topics: count = {len(AMC_TOPICS)}")
    assert len(AMC_TOPICS) == 100, f"Expected 100 AMC topics, got {len(AMC_TOPICS)}"
    for idx, t in enumerate(AMC_TOPICS):
        title, subj, sys_name, hallmark, ref_l, ref_u = t
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} at AMC #{idx}: {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} at AMC #{idx}: {title}"
        assert len(title) > 0 and len(hallmark) > 0, f"Empty title or hallmark at AMC #{idx}"
        assert ref_u.startswith("https://"), f"Invalid ref URL at AMC #{idx}: {ref_u}"
    print("  -> All 100 AMC topics PASSED validation!")

    out_path = os.path.join(os.path.dirname(__file__), "mega88_topics_a.py")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Generated Mega-Batch 88 Part A Topics (PLAB & AMC)\n\n")
        f.write(f"PLAB_TOPICS = {repr(PLAB_TOPICS)}\n\n")
        f.write(f"AMC_TOPICS = {repr(AMC_TOPICS)}\n")
    print(f"Successfully generated {out_path} with 200 topics!")

if __name__ == "__main__":
    validate_and_write()
